  6	var Router = (function () {
  7	  var _activeInterval = null;
  8	
  9	  function clearPolling() {
 10	    if (_activeInterval !== null) {
 11	      clearInterval(_activeInterval);
 12	      _activeInterval = null;
 13	    }
 14	  }
 15	
 16	  function setPolling(intervalFn, delayMs) {
 17	    clearPolling();
 18	    _activeInterval = setInterval(intervalFn, delayMs);
 19	  }
 20	
 21	  function updateNavActive(path) {
 22	    var navLinks = document.querySelectorAll('header nav a');
 23	    navLinks.forEach(function (link) {
 24	      var href = link.getAttribute('href') || '';
 25	      var linkPath = href.replace(/^#/, '') || '/';
 26	      link.classList.toggle('active', linkPath === path || (path === '' && linkPath === '/'));
 27	    });
 28	  }
 29	
 30	  function dispatch(hash) {
 31	    clearPolling();
 32	    var path = (hash || '').replace(/^#/, '') || '/';
 33	    var app = document.getElementById('app');
 34	    if (!app) return;
 35	
 36	    updateNavActive(path);
 37	
 38	    if (path === '/' || path === '') {
 39	      renderProjectList(app);
 40	      return;
 41	    }
 42	
 43	    var planMatch = path.match(/^\/projects\/([^/]+)\/([^/]+)\/plan$/);
 44	    if (planMatch) {
 45	      renderPlan(app, decodeURIComponent(planMatch[1]), decodeURIComponent(planMatch[2]));
 46	      return;
 47	    }
 48	
 49	    var synthesisMatch = path.match(/^\/projects\/([^/]+)\/([^/]+)\/synthesis$/);
 50	    if (synthesisMatch) {
 51	      renderSynthesis(app, decodeURIComponent(synthesisMatch[1]), decodeURIComponent(synthesisMatch[2]));
 52	      return;
 53	    }
 54	
 55	    var projectMatch = path.match(/^\/projects\/([^/]+)\/([^/]+)$/);
 56	    if (projectMatch) {
 57	      renderProjectDetail(app, decodeURIComponent(projectMatch[1]), decodeURIComponent(projectMatch[2]));
 58	      return;
 59	    }
 60	
 61	    var wpMatch = path.match(/^\/projects\/([^/]+)\/([^/]+)\/wp\/([^/]+)$/);
 62	    if (wpMatch) {
 63	      renderWorkPackageDetail(app, decodeURIComponent(wpMatch[1]), decodeURIComponent(wpMatch[2]), decodeURIComponent(wpMatch[3]));
 64	      return;
 65	    }
 66	
 67	    var runLogMatch = path.match(/^\/projects\/([^/]+)\/([^/]+)\/runs\/([^/]+)$/);
 68	    if (runLogMatch) {
 69	      renderRunLog(app, decodeURIComponent(runLogMatch[1]), decodeURIComponent(runLogMatch[2]), decodeURIComponent(runLogMatch[3]));
 70	      return;
 71	    }
 72	
 73	    /* ── Named singleton routes ──────────────────────────────── */
 74	    if (path === '/config') {
 75	      renderConfig(app);
 76	      return;
 77	    }
 78	
 79	    if (path === '/insights') {
 80	      renderInsights(app);
 81	      return;
 82	    }
 83	
 84	    if (path === '/knowledge') {
 85	      renderKnowledge(app);
 86	      return;
 87	    }
 88	
 89	    if (path === '/orchestrator') {
 90	      renderOrchestrator(app);
 91	      return;
 92	    }
 93	
 94	    if (path === '/strategy') {
 95	      renderStrategyList(app);
 96	      return;
 97	    }
 98	
 99	    var strategyDetailMatch = path.match(/^\/strategy\/([^/]+)$/);
100	    if (strategyDetailMatch) {

101	      renderStrategyDetail(app, decodeURIComponent(strategyDetailMatch[1]));
102	      return;
103	    }
104	
105	    app.innerHTML = '<p class="error-banner">Page not found: ' + escapeHtml(path) + '</p>';
106	  }
107	
108	  function navigate(hash) {
109	    window.location.hash = hash;
110	  }
111	
112	  function init() {
113	    window.addEventListener('hashchange', function () {
114	      dispatch(window.location.hash);
115	    });
116	    dispatch(window.location.hash);
117	  }
118	
119	  return {
120	    navigate: navigate,
121	    init: init,
122	    _setPolling: setPolling,
123	    _clearPolling: clearPolling,
124	  };
125	})();

  1	/* ============================================================
  2	   views/strategy.js — Strategy view (Repository List + Detail/Editor)
  3	   Section 4g of the MCP Server Dashboard SPA
  4	   Depends on: API, Router, escapeHtml, showLoading, showError
  5	   ============================================================ */
  6	
  7	
  8	/* ── renderStrategyList ──────────────────────────────────────
  9	   Renders the repository list at #/strategy.
 10	   Shows: label, folder names, vision status; Add Repository form.
 11	   ─────────────────────────────────────────────────────────── */
 12	function renderStrategyList(app) {
 13	  showLoading(app);
 14	
 15	  API.listRepos().then(function (repos) {
 16	    renderList(repos);
 17	  }).catch(function (err) {
 18	    showError(app, 'Failed to load repositories: ' + (err.message || String(err)));
 19	  });
 20	
 21	  function visionStatus(repo) {
 22	    var vision = repo.vision;
 23	    if (!vision) return '<span class="badge badge-blocked">No vision</span>';
 24	    var hasAny = (vision.short_term && vision.short_term.trim()) ||
 25	                 (vision.mid_term   && vision.mid_term.trim())   ||
 26	                 (vision.long_term  && vision.long_term.trim());
 27	    if (!hasAny) return '<span class="badge badge-blocked">No vision</span>';
 28	    var hasFull = (vision.short_term && vision.short_term.trim()) &&
 29	                  (vision.mid_term   && vision.mid_term.trim())   &&
 30	                  (vision.long_term  && vision.long_term.trim());
 31	    return hasFull
 32	      ? '<span class="badge badge-complete">Full vision</span>'
 33	      : '<span class="badge badge-in-progress">Partial vision</span>';
 34	  }
 35	
 36	  function buildTableHtml(repos) {
 37	    if (!repos.length) {
 38	      return '<p class="text-muted mt-16">No repositories declared yet. Use the form below to add one.</p>';
 39	    }
 40	    var rows = repos.map(function (r) {
 41	      var folderNames = (r.folder_names || []).map(escapeHtml).join(', ') || '<em class="text-muted">—</em>';
 42	      return (
 43	        '<tr>' +
 44	          '<td><a href="#/strategy/' + encodeURIComponent(r.id) + '">' + escapeHtml(r.label || r.id) + '</a></td>' +
 45	          '<td class="text-muted">' + escapeHtml(r.id) + '</td>' +
 46	          '<td>' + folderNames + '</td>' +
 47	          '<td>' + visionStatus(r) + '</td>' +
 48	        '</tr>'
 49	      );
 50	    }).join('');
 51	    return (
 52	      '<table class="data-table">' +
 53	        '<thead><tr>' +
 54	          '<th>Label</th>' +
 55	          '<th>ID</th>' +
 56	          '<th>Folder Names</th>' +
 57	          '<th>Vision</th>' +
 58	        '</tr></thead>' +
 59	        '<tbody>' + rows + '</tbody>' +
 60	      '</table>'
 61	    );
 62	  }
 63	
 64	  function renderList(repos) {
 65	    app.innerHTML =
 66	      '<div class="page-header">' +
 67	        '<h1>Strategy</h1>' +
 68	        '<p class="text-muted">Manage repository declarations and strategic vision.</p>' +
 69	      '</div>' +
 70	      buildTableHtml(repos) +
 71	      '<div class="card mt-24" style="max-width:560px">' +
 72	        '<h2 style="margin-top:0">Add Repository</h2>' +
 73	        '<form id="add-repo-form">' +
 74	          '<div class="form-group">' +
 75	            '<label class="form-label" for="new-repo-id">ID <span class="text-muted">(slug, e.g. my-project)</span></label>' +
 76	            '<input type="text" id="new-repo-id" class="form-control" placeholder="my-project" required>' +
 77	          '</div>' +
 78	          '<div class="form-group">' +
 79	            '<label class="form-label" for="new-repo-label">Label</label>' +
 80	            '<input type="text" id="new-repo-label" class="form-control" placeholder="My Project">' +
 81	          '</div>' +
 82	          '<div class="form-group">' +
 83	            '<label class="form-label" for="new-repo-folders">Folder Names <span class="text-muted">(comma-separated)</span></label>' +
 84	            '<input type="text" id="new-repo-folders" class="form-control" placeholder="my-project, my-project-dev">' +
 85	          '</div>' +
 86	          '<button type="submit" class="btn btn-primary">Add Repository</button>' +
 87	          '<div id="add-repo-msg"></div>' +
 88	        '</form>' +
 89	      '</div>';
 90	
 91	    var form = document.getElementById('add-repo-form');
 92	    if (!form) return;
 93	
 94	    form.addEventListener('submit', function (e) {
 95	      e.preventDefault();
 96	      var msgEl = document.getElementById('add-repo-msg');
 97	      var id = (document.getElementById('new-repo-id').value || '').trim();
 98	      var label = (document.getElementById('new-repo-label').value || '').trim();
 99	      var foldersRaw = (document.getElementById('new-repo-folders').value || '').trim();
100	      var folderNames = foldersRaw

101	        ? foldersRaw.split(',').map(function (f) { return f.trim(); }).filter(Boolean)
102	        : [];
103	
104	      if (!id) {
105	        msgEl.innerHTML = '<p class="error-banner">ID is required.</p>';
106	        return;
107	      }
108	
109	      msgEl.innerHTML = '';
110	      API.createRepo({ id: id, label: label || id, folder_names: folderNames })
111	        .then(function () {
112	          Router.navigate('#/strategy/' + encodeURIComponent(id));
113	        })
114	        .catch(function (err) {
115	          msgEl.innerHTML = '<p class="error-banner">Failed to create repository: ' + escapeHtml(err.message || String(err)) + '</p>';
116	        });
117	    });
118	  }
119	}
120	
121	/* ── renderStrategyDetail ────────────────────────────────────
122	   Renders the repository detail/editor at #/strategy/:repoId.
123	   Shows: editable label, folder names (add/remove), three-field
124	          vision editor (short-term, mid-term, long-term),
125	          save button, breadcrumb navigation.
126	   ─────────────────────────────────────────────────────────── */
127	function renderStrategyDetail(app, repoId) {
128	  showLoading(app);
129	
130	  API.getRepo(repoId).then(function (repo) {
131	    renderDetail(repo);
132	  }).catch(function (err) {
133	    if (err.code === 'NOT_FOUND' || (err.message && err.message.indexOf('404') !== -1)) {
134	      showError(app, 'Repository not found: ' + escapeHtml(repoId));
135	    } else {
136	      showError(app, 'Failed to load repository: ' + (err.message || String(err)));
137	    }
138	  });
139	
140	  function buildFolderListHtml(folderNames) {
141	    if (!folderNames || !folderNames.length) {
142	      return '<p class="text-muted" id="folder-empty-note">No folder names added yet.</p>';
143	    }
144	    return folderNames.map(function (f, i) {
145	      return (
146	        '<div class="folder-entry" style="display:flex;align-items:center;gap:8px;margin-bottom:6px">' +
147	          '<input type="text" class="form-control folder-name-input" data-folder-idx="' + i + '" value="' + escapeHtml(f) + '" style="flex:1">' +
148	          '<button type="button" class="btn btn-danger btn-sm" data-remove-folder="' + i + '">Remove</button>' +
149	        '</div>'
150	      );
151	    }).join('');
152	  }
153	
154	  /* Reads all folder name inputs from the DOM in index order. */
155	  function collectFolderNamesFromDOM() {
156	    var result = [];
157	    document.querySelectorAll('.folder-name-input').forEach(function (inp) {
158	      var val = inp.value.trim();
159	      if (val) result.push(val);
160	    });
161	    return result;
162	  }
163	
164	  function renderDetail(repo) {
165	    var vision = repo.vision || {};
166	    /* Working copy — mutated by add/remove, then merged with DOM on save. */
167	    var folderNames = (repo.folder_names || []).slice();
168	
169	    function rebuildFolderSection() {
170	      var container = document.getElementById('folder-list');
171	      if (container) {
172	        container.innerHTML = buildFolderListHtml(folderNames);
173	        wireRemoveButtons();
174	      }
175	    }
176	
177	    function wireRemoveButtons() {
178	      var container = document.getElementById('folder-list');
179	      if (!container) return;
180	      container.querySelectorAll('[data-remove-folder]').forEach(function (btn) {
181	        btn.addEventListener('click', function () {
182	          /* Capture any in-flight edits before splicing */
183	          folderNames = collectFolderNamesFromDOM();
184	          var idx = parseInt(btn.getAttribute('data-remove-folder'), 10);
185	          folderNames.splice(idx, 1);
186	          rebuildFolderSection();
187	        });
188	      });
189	    }
190	
191	    app.innerHTML =
192	      '<div class="breadcrumb">' +
193	        '<a href="#/strategy">Strategy</a>' +
194	        ' &rsaquo; ' +
195	        escapeHtml(repo.label || repo.id) +
196	      '</div>' +
197	      '<div class="page-header">' +
198	        '<h1>' + escapeHtml(repo.label || repo.id) + '</h1>' +
199	        '<p class="text-muted">ID: <code>' + escapeHtml(repo.id) + '</code></p>' +
200	      '</div>' +

201	      '<div class="card" style="max-width:680px">' +
202	        '<form id="detail-form">' +
203	          '<h2 style="margin-top:0">Metadata</h2>' +
204	          '<div class="form-group">' +
205	            '<label class="form-label" for="repo-label">Label</label>' +
206	            '<input type="text" id="repo-label" class="form-control" value="' + escapeHtml(repo.label || '') + '">' +
207	          '</div>' +
208	          '<div class="form-group">' +
209	            '<label class="form-label">Folder Names</label>' +
210	            '<div id="folder-list">' + buildFolderListHtml(folderNames) + '</div>' +
211	            '<div style="display:flex;gap:8px;margin-top:8px;align-items:center">' +
212	              '<input type="text" id="new-folder-input" class="form-control" placeholder="Add folder name\u2026" style="flex:1">' +
213	              '<button type="button" id="add-folder-btn" class="btn btn-secondary btn-sm">Add</button>' +
214	            '</div>' +
215	          '</div>' +
216	          '<h2 style="margin-top:24px">Strategic Vision</h2>' +
217	          '<div class="form-group">' +
218	            '<label class="form-label" for="vision-short">Short-term</label>' +
219	            '<textarea id="vision-short" class="form-control" rows="4" placeholder="Short-term goals and priorities\u2026">' + escapeHtml(vision.short_term || '') + '</textarea>' +
220	          '</div>' +
221	          '<div class="form-group">' +
222	            '<label class="form-label" for="vision-mid">Mid-term</label>' +
223	            '<textarea id="vision-mid" class="form-control" rows="4" placeholder="Mid-term direction and milestones\u2026">' + escapeHtml(vision.mid_term || '') + '</textarea>' +
224	          '</div>' +
225	          '<div class="form-group">' +
226	            '<label class="form-label" for="vision-long">Long-term</label>' +
227	            '<textarea id="vision-long" class="form-control" rows="4" placeholder="Long-term aspirations and vision\u2026">' + escapeHtml(vision.long_term || '') + '</textarea>' +
228	          '</div>' +
229	          '<div style="display:flex;gap:12px;align-items:center">' +
230	            '<button type="submit" class="btn btn-primary">Save Changes</button>' +
231	            '<a href="#/strategy" class="btn btn-secondary">Cancel</a>' +
232	          '</div>' +
233	          '<div id="detail-msg"></div>' +
234	        '</form>' +
235	      '</div>';
236	
237	    wireRemoveButtons();
238	
239	    /* ── Add folder button ─────────────────────────────────── */
240	    var addFolderBtn = document.getElementById('add-folder-btn');
241	    var newFolderInput = document.getElementById('new-folder-input');
242	    if (addFolderBtn && newFolderInput) {
243	      function doAddFolder() {
244	        var val = newFolderInput.value.trim();
245	        if (!val) return;
246	        /* Capture any in-flight edits before pushing */
247	        folderNames = collectFolderNamesFromDOM();
248	        folderNames.push(val);
249	        newFolderInput.value = '';
250	        rebuildFolderSection();
251	      }
252	
253	      addFolderBtn.addEventListener('click', doAddFolder);
254	      newFolderInput.addEventListener('keydown', function (e) {
255	        if (e.key === 'Enter') {
256	          e.preventDefault();
257	          doAddFolder();
258	        }
259	      });
260	    }
